"""Add the current sign-in view; preserve approved narration and AAC audio exactly."""
import argparse,hashlib,json,subprocess
from pathlib import Path
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--source',type=Path,required=True);p.add_argument('--screen',type=Path,required=True);p.add_argument('--directory',type=Path,required=True);a=p.parse_args();o=a.directory;o.mkdir(parents=True,exist_ok=True)
# The sign-in view occupies the existing solution-introduction phone frame only.
filters="[1:v]scale=500:978[auth];[0:v][auth]overlay=1300:50:enable='between(t,26,32)',drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf:text='Google sign-in. No passcode.':x=120:y=650:fontsize=32:fontcolor=0x234b3d:enable='between(t,26,37)',drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf:text='Shared daily allowance. Saved learning remains available.':x=120:y=710:fontsize=26:fontcolor=0x607568:enable='between(t,26,37)'[v]"
target=o/'LingoLive-Demo.mp4';subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-y','-reinit_filter','0','-i',str(a.source),'-loop','1','-i',str(a.screen),'-filter_complex_threads','1','-filter_complex',filters,'-map','[v]','-map','0:a','-c:v','libx264','-preset','veryfast','-crf','20','-pix_fmt','yuv420p','-r','25','-threads','2','-c:a','copy','-t','197.048','-movflags','+faststart',str(target)],check=True)
def audio_hash(p):return hashlib.sha256(subprocess.check_output(['ffmpeg','-v','error','-i',str(p),'-vn','-c:a','copy','-f','adts','-'])).hexdigest()
assert audio_hash(a.source)==audio_hash(target)
subprocess.run(['ffmpeg','-v','error','-i',str(target),'-f','null','-'],check=True)
info=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_format','-show_streams','-of','json',str(target)]));seconds=float(info['format']['duration']);assert 180<=seconds<=240
report=json.loads(a.source.with_name('video-verification.json').read_text());report.update(sha256=hashlib.sha256(target.read_bytes()).hexdigest(),bytes=target.stat().st_size,seconds=seconds,demo_version='3.1',app_version='1.12 sign-in view; 1.11 readback; 1.9 original scenes',current_google_signin_view_added=True,signin_view_seconds=[26,32],actual_google_account_login_completed_in_video=False,narration_changed=False,new_audio_generated=False,aac_audio_bitstream_unchanged=True,aac_audio_sha256=audio_hash(target),all_29_previously_verified_voices_preserved=True)
(o/'video-verification.json').write_text(json.dumps(report,indent=2)+'\n');audio=json.loads(a.source.with_name('audio-verification.json').read_text());audio.update(aac_audio_bitstream_unchanged=True,verification_of_update='AAC bitstream matches the prior export that passed every source-voice waveform check; new export decodes successfully.');(o/'audio-verification.json').write_text(json.dumps(audio,indent=2)+'\n');print(json.dumps({'seconds':seconds,'audio_unchanged':True,'new_narration':False,'sha256':report['sha256']}))
